// Zero-bloat, Modular WordPress-like Template Engine powered by Eleventy (11ty)

const htmlmin = require("html-minifier");

module.exports = function (eleventyConfig) {

  // 1. PASSTHROUGH COPIES (Directly to output root)
  eleventyConfig.addPassthroughCopy({ "public/css": "css" });
  eleventyConfig.addPassthroughCopy({ "public/js": "js" });
  eleventyConfig.addPassthroughCopy({ "public/robots.txt": "robots.txt" });
  eleventyConfig.addPassthroughCopy({ "public/_headers": "_headers" });
  eleventyConfig.addPassthroughCopy({ "public/_redirects": "_redirects" });

  // 2. CUSTOM FILTERS
  // Format Date to YYYY-MM-DD for sitemaps
  eleventyConfig.addFilter("toISO", (dateVal) => {
    const d = dateVal ? new Date(dateVal) : new Date();
    return d.toISOString().slice(0, 10);
  });

  // Active Nav Helper
  eleventyConfig.addFilter("isActiveNav", (pageUrl, targetUrl) => {
    if (targetUrl === "/" && pageUrl === "/") return "active";
    if (targetUrl !== "/" && pageUrl.startsWith(targetUrl)) return "active";
    return "";
  });

  // 3. HTML MINIFICATION (Production builds)
  eleventyConfig.addTransform("htmlmin", function (content, outputPath) {
    if (outputPath && outputPath.endsWith(".html")) {
      return htmlmin.minify(content, {
        useShortDoctype: true,
        removeComments: true,
        collapseWhitespace: true
      });
    }
    return content;
  });

  return {
    dir: {
      input: "src",
      includes: "_includes",
      data: "_data",
      output: "_site"
    },
    templateFormats: ["njk", "md", "html"],
    htmlTemplateEngine: "njk",
    markdownTemplateEngine: "njk"
  };
};

