    } else {
      themeIcon.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"></path></svg>`;
    }
  }

  // Initial icon sync
  const currentTheme = document.documentElement.getAttribute('data-theme') || 'light';
  updateThemeIcon(currentTheme);

  if (themeToggleBtn) {
    themeToggleBtn.addEventListener('click', () => {
      const activeTheme = document.documentElement.getAttribute('data-theme');
      const newTheme = activeTheme === 'dark' ? 'light' : 'dark';
      document.documentElement.setAttribute('data-theme', newTheme);
      localStorage.setItem('frankbase_theme', newTheme);
      updateThemeIcon(newTheme);
    });
  }

  // 2. Mobile Navigation Toggle
  const hamburger = document.getElementById('hamburger');
  const mobileMenu = document.getElementById('mobile-menu');

  if (hamburger && mobileMenu) {
    hamburger.addEventListener('click', () => {
      mobileMenu.classList.toggle('open');
      const isOpen = mobileMenu.classList.contains('open');
      hamburger.setAttribute('aria-expanded', isOpen);
    });
  }

  // 3. Expandable / Collapsible Accordion Cards (Legal Hub)
  const accordionCards = document.querySelectorAll('.accordion-card');
  accordionCards.forEach(card => {
    const btn = card.querySelector('.accordion-header-btn');
    if (btn) {
      btn.addEventListener('click', () => {
        const isActive = card.classList.contains('active');
        card.classList.toggle('active');
        btn.setAttribute('aria-expanded', !isActive);
      });
    }
  });

  // Expand All / Collapse All Controls
  const expandAllBtn = document.getElementById('expand-all-btn');
  const collapseAllBtn = document.getElementById('collapse-all-btn');

  if (expandAllBtn) {
    expandAllBtn.addEventListener('click', () => {
      accordionCards.forEach(card => {
        card.classList.add('active');
        const btn = card.querySelector('.accordion-header-btn');
        if (btn) btn.setAttribute('aria-expanded', 'true');
      });
    });
  }

  if (collapseAllBtn) {
    collapseAllBtn.addEventListener('click', () => {
      accordionCards.forEach(card => {
        card.classList.remove('active');
        const btn = card.querySelector('.accordion-header-btn');
        if (btn) btn.setAttribute('aria-expanded', 'false');
      });
    });
  }

  // URL Hash Deep Linking (Auto-Expand target card on page load)
  if (window.location.hash) {
    const targetId = window.location.hash.substring(1);
    const targetCard = document.getElementById(targetId);
    if (targetCard && targetCard.classList.contains('accordion-card')) {
      targetCard.classList.add('active');
      const btn = targetCard.querySelector('.accordion-header-btn');
      if (btn) btn.setAttribute('aria-expanded', 'true');
      setTimeout(() => {
        targetCard.scrollIntoView({ behavior: 'smooth', block: 'center' });
      }, 200);
    }
  }

  // 4. Search Bar Interactivity
  const searchInput = document.getElementById('global-search');
  if (searchInput) {
    searchInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        const query = searchInput.value.trim();
        if (query) {
          const targetSection = document.getElementById('tracks');
          if (targetSection) {
            targetSection.scrollIntoView({ behavior: 'smooth' });
          }
        }
      }
    });
  }

  // 5. Central Lead Ingestion Form Handler
  const contactForm = document.getElementById('frankbase-contact-form');
  if (contactForm) {
    contactForm.addEventListener('submit', async (e) => {
      e.preventDefault();
      const submitBtn = contactForm.querySelector('button[type="submit"]');
      const formFeedback = document.getElementById('form-feedback');

      const formData = new FormData(contactForm);
      const payload = {
        name: formData.get('name') || '',
        email: formData.get('email') || '',
        phone: formData.get('phone') || '',
        message: formData.get('message') || '',
        source_domain: 'frankbase.com',
        tenant_id: 'frankbase_hub',
        timestamp: new Date().toISOString()
      };

      try {
        if (submitBtn) {
          submitBtn.disabled = true;
          submitBtn.textContent = 'Sending...';
        }

        const response = await fetch('https://mmcentral.pages.dev/api/submit-lead', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        });

        if (response.ok) {
          contactForm.reset();
          if (formFeedback) {
            formFeedback.style.display = 'block';
            formFeedback.className = 'form-feedback success';
            formFeedback.textContent = 'Message sent successfully! Our team will get in touch shortly.';
          }
        } else {
          throw new Error('Network error');
        }
      } catch (err) {
        if (formFeedback) {
          formFeedback.style.display = 'block';
          formFeedback.className = 'form-feedback error';
          formFeedback.textContent = 'Failed to send message online. Please reach out via WhatsApp (+91 7070133396) or email support@frankbase.com.';
        }
      } finally {
        if (submitBtn) {
          submitBtn.disabled = false;
          submitBtn.textContent = 'Send Message';
        }
      }
    });
  }
});

// eleventy.config.js — FrankBase Main Knowledge Hub
// Zero-bloat, Modular WordPress-like Template Engine powered by Eleventy (11ty)

let htmlmin;
try {
  htmlmin = require("html-minifier");
} catch (e) {
  htmlmin = null;
}

module.exports = function (eleventyConfig) {

  // 1. PASSTHROUGH COPIES (Directly to output root)
  eleventyConfig.addPassthroughCopy({ "public/css": "css" });
  eleventyConfig.addPassthroughCopy({ "public/js": "js" });
  eleventyConfig.addPassthroughCopy({ "public/robots.txt": "robots.txt" });
  eleventyConfig.addPassthroughCopy({ "public/_headers": "_headers" });
  eleventyConfig.addPassthroughCopy({ "public/_redirects": "_redirects" });

  // 2. CUSTOM FILTERS
  // Format Date to YYYY-MM-DD for sitemaps
  eleventyConfig.addFilter("toISO", (dateVal) => {
    const d = dateVal ? new Date(dateVal) : new Date();
    return d.toISOString().slice(0, 10);
  });

  // Active Nav Helper
  eleventyConfig.addFilter("isActiveNav", (pageUrl, targetUrl) => {
    if (!pageUrl) return "";
    if (targetUrl === "/" && pageUrl === "/") return "active";
    if (targetUrl !== "/" && pageUrl.startsWith(targetUrl)) return "active";
    return "";
  });

  // 3. OPTIONAL HTML MINIFICATION
  if (htmlmin) {
    eleventyConfig.addTransform("htmlmin", function (content, outputPath) {
      if (outputPath && outputPath.endsWith(".html")) {
        return htmlmin.minify(content, {
          useShortDoctype: true,
          removeComments: true,
          collapseWhitespace: true
        });
      }
      return content;
    });
  }

  return {
    dir: {
      input: "src",
      includes: "_includes",
      data: "_data",
      output: "_site"
    },
    templateFormats: ["njk", "md", "html"],
    htmlTemplateEngine: "njk",
    markdownTemplateEngine: "njk"
  };
};

